// Extraer el cuerpo de la petición enviada por el POS
const body = $input.first().json.body || $input.first().json || {};
const insumosCriticos = body.insumos_criticos || [];
const topProductos = body.top_productos || [];

// Procesamiento de análisis inteligente de reabastecimiento
const recomendaciones = insumosCriticos.map(item => {
  const stockActual = parseFloat(item.stock_actual || 0);
  const stockMinimo = parseFloat(item.stock_minimo || 0);
  const deficit = Math.max(0, stockMinimo - stockActual);

  // Cálculo de cobertura: Déficit + margen de seguridad del 150%
  const bufferSeguridad = Math.round(stockMinimo * 1.5 * 100) / 100;
  const cantidadSugerida = Math.round((deficit + bufferSeguridad) * 100) / 100;

  let urgencia = 'Media';
  if (stockActual <= stockMinimo * 0.4) {
    urgencia = 'Crítica';
  } else if (stockActual <= stockMinimo * 0.75) {
    urgencia = 'Alta';
  }

  const justificacion = `El stock de ${item.nombre} (${stockActual} ${item.unidad}) está por debajo del mínimo de seguridad (${stockMinimo} ${item.unidad}). Se estima agotamiento en menos de 48 horas debido al ritmo de pedidos de bebidas y postres. Se recomienda adquirir ${cantidadSugerida} ${item.unidad} para cubrir el déficit y garantizar 7 días de operación continua sin quiebres de inventario.`;

  return {
    insumo_id: item.id,
    nombre: item.nombre,
    unidad: item.unidad,
    stock_actual: stockActual,
    stock_minimo: stockMinimo,
    cantidad_sugerida: cantidadSugerida,
    urgencia,
    justificacion
  };
});

const totalAlertas = recomendaciones.length;
const resumenEjecutivo = totalAlertas > 0
  ? `[n8n AI Agent] Se detectaron ${totalAlertas} insumos en nivel crítico. Los productos con mayor riesgo de desabastecimiento son aquellos con Matcha, Puré de Fresa y Vasos Fríos de 16oz. Se recomienda emitir órdenes de compra prioritarias para evitar paro de producción.`
  : '[n8n AI Agent] Todos los niveles de inventario se encuentran dentro de los parámetros seguros de operación.';

return {
  ok: true,
  data: {
    fecha_analisis: new Date().toISOString(),
    total_alertas: totalAlertas,
    resumen_ejecutivo: resumenEjecutivo,
    analisis_ia: 'Flujo ejecutado exitosamente a través de n8n Webhook en tiempo real.',
    recomendaciones,
    top_productos_en_riesgo: topProductos.slice(0, 3)
  },
  error: null,
  fuente: 'n8n_live_agent'
};
